        value: state.email,
        touched: state.touched.email,
        onInput: (val) => {
          state.email = val;
          state.touched.email = true;
          rerender();
        },
      }),
      FormField({
        id: "phone",
        label: "Phone Number",
        required: false,
        type: "tel",
