    );

    if (formEl && formEl.parentNode) {
      formEl.parentNode.replaceChild(newForm, formEl);
    }
    formEl = newForm;
    return formEl;
  }

  function rerender() {
    render();
  }

  function handleSubmit(e) {
    e.preventDefault();

    // Mark all required fields as touched on submit attempt
    state.touched.fullName = true;
    state.touched.email = true;

